mapper.select:
select * from mes3_project_management t
del_flag = 0
and project_name like CONCAT('%',#{projectName},'%')
and project_level in
#{item}
and project_type in
#{item}
and project_source in
#{item}
and sys_org_id = #{sysOrgId}
and exists ( select 1 from mes3_project_management_action a where a.project_id = t.id and ( DATE_FORMAT( plan_completion_time, '%Y-%m' ) in
concat(#{year}, '-', LPAD(#{month}, 2, '0'))
or DATE_FORMAT( real_completion_time, '%Y-%m' ) in
concat(#{year}, '-', LPAD(#{month}, 2, '0'))
) )
order by create_time desc

select
a.id,
project_code,
project_name,
project_level,
project_type,
sys_org_id,

    IFNULL(
        SUM(
            case
                when b.document_month=#{month}
                then ROUND(ifnull(b.add_total_score,0.0), 2)
                else 0.0
            end
        ),0.0
    ) as ${'month' + month}

from mes3_project_management a
left join mes3_project_management_document b on a.id=b.project_id
WHERE a.del_flag = 0
and b.document_year = #{year}

    and project_name like CONCAT('%',#{projectName},'%')


    and project_level in

        #{item}



    and project_type in

        #{item}



    and project_source in

        #{item}



    and sys_org_id = #{sysOrgId}

group by a.id,a.project_code,a.project_name,a.project_level,a.project_type,a.sys_org_id

select t.*, ifnull(round(t.reward_personal / a.reward_count * 100, 2), 0) as contribution
from (
    select t.project_id as id, leader_user_id, ifnull(sum(reward), 0) as reward_personal,

            round(ifnull(sum(case when month_str = lpad(#{month}, 2, '0') then reward else 0 end), 0), 2) as ${'month' + month}

    from (
        select t.project_id, t.node_id, t.leader_user_id, t.reward, a.month_str
        from (
            select project_id, node_id, leader_user_id, sum(reward) as reward
            from mes3_project_management_action
            where del_flag = 0 and project_id in(${projectIds})

                and leader_user_id = #{userId}

            group by project_id, node_id, leader_user_id
        ) t
        left join (
            select project_id, node_id, month_str
            from(
                select
                    project_id, node_id, DATE_FORMAT(max(real_completion_time), '%m') as month_str,
                    count(1) as node_count,
                    sum(case when action_state in(1,4) then 1 else 0 end) as finish_count,
                    max(real_completion_time) as max_month
                from mes3_project_management_action
                where del_flag = 0
                group by project_id, node_id
            ) t
            where node_count = finish_count
            and max_month like concat(#{year}, '%')
        ) a on t.project_id = a.project_id and t.node_id = a.node_id
        where t.leader_user_id is not null

            and a.node_id is not null

    ) t
    group by t.project_id, leader_user_id
) t
left join (
    select project_id, sum(reward) reward_count
    from mes3_project_management_action
    where del_flag = 0
    group by project_id
) a on t.id = a.project_id
order by t.id, reward_personal desc
